\label{ass:convex}
The function $f:\mathbb R^d\to\mathbb R$ is twice continuously differentiable and
convex. Thus, for every $x,y\in\mathbb R^d$,
\begin{equation}\label{eq:convexity}
 f(y)\ge f(x)+\nabla f(x)^T(y-x).
\end{equation}

\label{ass:level}
The set
\begin{equation}\label{eq:level-set}
\mathcal C_0=\{x\in\mathbb R^d:f(x)\le f(x^0)\}
\end{equation}
is bounded.

\label{ass:hessian}
There exists a constant $H>0$ such that
\begin{equation}\label{eq:hessian-lipschitz}
 \|\nabla^2f(x)-\nabla^2f(y)\|\le2H\|x-y\|
 \qquad\text{for all }x,y\in\mathcal C_0.
\end{equation}

\label{lem:invariance}
Under Assumptions~\ref{ass:convex}--\ref{ass:hessian}, let
$x\in\mathcal C_0$, let $S$ be a linear subspace containing
$\nabla f(x)$, and let $s$ be defined by the cubic subproblem
\eqref{eq:model}.  The minimizer exists and is unique, and it satisfies
\begin{equation}\label{eq:model-stationarity}
 \Pi_S\bigl(\nabla f(x)+\nabla^2f(x)s+H\|s\|s\bigr)=0.
\end{equation}
Moreover, $[x,x+s]\subseteq\mathcal C_0$, and
\begin{equation}\label{eq:two-decreases}
 f(x)-f(x+s)
 \ge\tfrac12s^T\nabla^2f(x)s+\tfrac{2H}{3}\|s\|^3.
\end{equation}
If $\nabla f(x)\ne0$, then $s\ne0$ and the decrease is strict.

\label{lem:defect}
Under Assumptions~\ref{ass:convex}--\ref{ass:hessian}, let $x$, $S$, and
$s$ be as in Lemma~\ref{lem:invariance}.  Then
\begin{equation}\label{eq:descent-defect}
 \|\Pi_S\nabla f(x+s)\|
 \le2H\|s\|^2
 \le(18H)^{1/3}\bigl(f(x)-f(x+s)\bigr)^{2/3}.
\end{equation}

\label{lem:gradient-decrease}
Under Assumptions~\ref{ass:convex}--\ref{ass:hessian}, let $x$, $S$, and
$s$ be as in Lemma~\ref{lem:invariance}.  Suppose
$\nabla f(x^0)\ne0$. Then $L_0+\sqrt{2HL_0D_0}>0$, and
\begin{equation}\label{eq:gradient-budget}
 f(x)-f(x+s)\ge\frac{\|\nabla f(x)\|^2}{3\bigl(L_0+\sqrt{2HL_0D_0}\bigr)}.
\end{equation}

\label{lem:weights}
The weights in Algorithm~\ref{alg:cubic} satisfy, for $k\ge0$,
\begin{equation}\label{eq:weights}
 \omega_k^2-\omega_{k-1}^2=\omega_k,\qquad
 \sum_{i=0}^k\omega_i=\omega_k^2,\qquad
 \frac{k+2}{2}\le\omega_k\le k+1.
\end{equation}
For every $k\ge0$, $1/2\le\omega_{k+1}-\omega_k<1$.

\label{prop:iteration}
Under Assumptions~\ref{ass:convex}--\ref{ass:hessian},
Algorithm~\ref{alg:cubic} is well defined, remains in $\mathcal C_0$,
and satisfies $f(x^{k+1})\le f(x^k)$. Its corrected gradient obeys
\begin{equation}\label{eq:orthogonalities}
 h^k\perp(x^k-x^0),\qquad h^k\perp z^{k-1},\qquad
 \|h^k\|\le\|\nabla f(x^k)\|.
\end{equation}
If $\nabla f(x^0)\ne0$, then
\begin{align}
 \|\nabla f(x^k)\|^2
 &\le3\bigl(L_0+\sqrt{2HL_0D_0}\bigr)\bigl(f(x^k)-f(x^{k+1})\bigr),
 \label{eq:algorithm-gradient}\\
 \|e^{k+1}\|
 &\le(18H)^{1/3}\bigl(f(x^k)-f(x^{k+1})\bigr)^{2/3}.
 \label{eq:defect-budget}
\end{align}

\label{lem:reserve}
For all integers $0\le \ell\le k$,
\begin{equation}\label{eq:window-reserve}
\begin{aligned}
 \omega_k^2\Delta_{k+1}
 +\frac34\sum_{i=\ell}^k\omega_i^2d_i
 &\le \omega_{\ell-1}^2\Delta_\ell
 +(x^0-x^\star)^T(z^k-z^{\ell-1})\\
 &\quad
 -\frac{\|z^k\|^2-\|z^{\ell-1}\|^2}{12\bigl(L_0+\sqrt{2HL_0D_0}\bigr)}
 +D_0\sum_{i=\ell}^k\omega_i\|e^i\|.
\end{aligned}
\end{equation}

\label{lem:prefix}
For every integer $k\ge0$,
\begin{equation}\label{eq:window-prefix}
\begin{aligned}
 \omega_k^2\Delta_{k+1}
 +\frac14\sum_{i=0}^k\omega_i^2d_i
 &\le3\bigl(L_0+\sqrt{2HL_0D_0}\bigr)\|x^0-x^\star\|^2
   +\frac{512}{3}HD_0^3\log(k+1).
\end{aligned}
\end{equation}
Consequently,
\begin{equation}\label{eq:window-aggregate-bound}
\begin{aligned}
 \|z^k\|^2
 &\le12\bigl(L_0+\sqrt{2HL_0D_0}\bigr)\bigl(1+\log(k+1)\bigr)\\
 &\quad\cdot\Bigl[3\bigl(L_0+\sqrt{2HL_0D_0}\bigr)
                 \|x^0-x^\star\|^2+\tfrac{512}{3}HD_0^3\Bigr].
\end{aligned}
\end{equation}
The initial gap and every shifted prefix gap satisfy
\begin{equation}\label{eq:prefix-gap}
\begin{aligned}
 \Delta_0&\le3\bigl(L_0+\sqrt{2HL_0D_0}\bigr)\|x^0-x^\star\|^2,\\
 \Delta_{\ell-1}&\le\frac{4(1+\log\ell)}{\ell^2}
 \Bigl[3\bigl(L_0+\sqrt{2HL_0D_0}\bigr)\|x^0-x^\star\|^2
                          +\tfrac{512}{3}HD_0^3\Bigr]
 \quad(\ell\ge1).
\end{aligned}
\end{equation}

\label{lem:window}
Fix an integer $\ell\ge1$, and let $k\ge \ell$ be the first index such that
\[
 \omega_k\ge2\omega_{\ell-1}.
\]
Then
\begin{equation}\label{eq:window-gap-recurrence}
\begin{aligned}
 \omega_k^2\Delta_{k+1}
 +\frac14\sum_{i=\ell}^k\omega_i^2d_i
 &\le\omega_{\ell-1}^2\Delta_\ell\\
 &\quad+16\sqrt{1+\log\ell}
 \Bigl[3\bigl(L_0+\sqrt{2HL_0D_0}\bigr)\|x^0-x^\star\|^2
                       +\tfrac{512}{3}HD_0^3\Bigr].
\end{aligned}
\end{equation}

\label{lem:local-projection}
Under Assumptions~\ref{ass:convex}--\ref{ass:hessian} and~\ref{ass:local},
let $P^k$ be the orthogonal
projector onto $\mathcal S^k$ for the inner product $v^T\nabla^2f(x^\star)w$.
There exists a finite constant $C_1$, depending on the problem
and the fixed coefficient $H$ but independent of $k$ and the choice
of search space, such that, for all sufficiently large $k$,
\begin{equation}\label{eq:local-projection}
 \begin{aligned}
 x^{k+1}-x^\star&=(I-P^k)(x^k-x^\star)+w^k,\\
 w^k&\in\mathcal S^k,\qquad
 \|w^k\|_\star\le C_1\|x^k-x^\star\|_\star^2.
 \end{aligned}
\end{equation}
Consequently, using the distance defined just above the lemma,
\begin{equation}\label{eq:local-distance-bound}
 \|x^{k+1}-x^\star\|_\star\le\operatorname{dist}_\star(x^k-x^\star,\mathcal S^k)+C_1\|x^k-x^\star\|_\star^2.
\end{equation}

\label{thm:local-pl}
Under Assumptions~\ref{ass:convex}--\ref{ass:hessian}, consider
a nonstationary run of the fixed-coefficient model steps, with
search spaces containing the current gradient and with restarts
permitted. Their decrease bounds are
\begin{equation}\label{eq:pl-two-budgets}
 \begin{aligned}
 f(x^k)-f(x^{k+1})&\ge
 \frac{\|\nabla f(x^k)\|^2}{3(L_0+\sqrt{2HL_0D_0})},\\
 f(x^k)-f(x^{k+1})&\ge
 \frac{2H}{3}\|x^{k+1}-x^k\|^3.
 \end{aligned}
\end{equation}
For an infinite run, suppose an accumulation point $\bar x$ has a
neighborhood on which, for some $r,\mu>0$,
\begin{equation}\label{eq:local-pl-condition}
 \|\nabla f(x)\|^2\ge2\mu(f(x)-f_\star)
 \quad\text{for all }x\in\mathcal C_0\cap B(\bar x,r).
\end{equation}
Decrease $\mu$ if necessary so that
$0<2\mu<3(L_0+\sqrt{2HL_0D_0})$, and put
\[
 q=1-\frac{2\mu}{3(L_0+\sqrt{2HL_0D_0})}\in(0,1).
\]
Then $\bar x$ is a minimizer and,
for some $k_0$ and every $k\ge k_0$,
\begin{equation}\label{eq:local-pl-conclusions}
 \begin{aligned}
 f(x^{k+1})-f_\star&\le q(f(x^k)-f_\star),\\
 \sum_{i=k}^\infty\|x^{i+1}-x^i\|
 &\le\frac{(f(x^k)-f_\star)^{1/3}}
              {(2H/3)^{1/3}(1-q^{1/3})},\\
 \|x^k-\bar x\|
 &\le\frac{(f(x^{k_0})-f_\star)^{1/3}}
              {(2H/3)^{1/3}(1-q^{1/3})}\,q^{(k-k_0)/3}.
 \end{aligned}
\end{equation}
Thus the gaps converge Q-linearly and the iterates converge
R-linearly to $\bar x$. Neither uniqueness of the minimizer nor a
positive-definite Hessian is required. The PL constant is used only
in the analysis. Finite termination at a stationary point is the
immediate alternative.

\label{lem:epoch-bound}
Under Assumptions~\ref{ass:convex}--\ref{ass:hessian}, start an
epoch at $y^0\in\mathcal C_0$ with an integer weight $t\ge1$ and
aggregate $t\nabla f(y^0)$.
For every prefix of $k+1$ steps, where $0\le k\le4t$,
\begin{equation}\label{eq:epoch-bound}
\begin{aligned}
 \omega_k^2\bigl(f(y^{k+1})-f_\star\bigr)
 &\le(t^2-t)\bigl(f(y^0)-f_\star\bigr)
       +\frac32\bigl(L_0+\sqrt{2HL_0D_0}\bigr) D_0^2\\
 &\quad+\frac{32}{3}HD_0^3
          \sum_{i=1}^k\frac{\omega_i^3}{\omega_{i-1}^4}.
\end{aligned}
\end{equation}
In particular, the completed epoch satisfies
\begin{equation}\label{eq:completed-epoch}
 f(y^{4t+1})-f_\star
 \le\frac{(t^2-t)\bigl(f(y^0)-f_\star\bigr)
              +\tfrac32\bigl(L_0+\sqrt{2HL_0D_0}\bigr) D_0^2
              +\tfrac{1024}{3}HD_0^3}{9t^2}.
\end{equation}
The incoming previous displacement may be retained from before
the epoch.

\label{thm:restarted-rate}
Under Assumptions~\ref{ass:convex}--\ref{ass:hessian}, use the
restart rule above with exact model solves and projections. Index
the concatenated trajectory by the total number $K$ of cubic steps.
It is monotone, remains in $\mathcal C_0$, and satisfies
\begin{equation}\label{eq:restarted-rate}
 f(x^K)-f_\star\le
 \frac{81D_0^2}{(K+1)^2}
 \left[\frac32\bigl(L_0+\sqrt{2HL_0D_0}\bigr)+\frac{1024}{3}HD_0\right]
 \qquad(K\ge0),
\end{equation}
Under Assumption~\ref{ass:local}, it also retains the local linear
guarantee of Theorem~\ref{thm:local}.

\label{cor:explicit-transition}
Under the assumptions of Theorem~\ref{thm:automatic-acceleration},
suppose $\nabla^2 f(x^\star)\succ0$. Write
$\mu_\star=\lambda_{\min}(\nabla^2 f(x^\star))$ and retain
$\kappa_\star$ from that theorem and $H$ from
Assumption~\ref{ass:hessian}. Define the
local objective threshold and a sufficient entry index by
\begin{align*}
 \varepsilon_{\mathrm{loc}}&=\frac{\mu_\star^3}{2^{27}H^2},\\
 K_{\mathrm{entry}}&=\left\lceil72D_0
 \sqrt{\frac{\tfrac32(L_0+\sqrt{4HL_0D_0})
                   +\tfrac{2048}{3}HD_0}
                  {\varepsilon_{\mathrm{loc}}}}\right\rceil.
\end{align*}
Let $T_{\mathrm{adapt}}$ be the smallest power of two satisfying both
\begin{align*}
 T_{\mathrm{adapt}}&\ge K_{\mathrm{entry}}+2,\\
 T_{\mathrm{adapt}}&\ge\frac{58\sqrt{\kappa_\star}}{\log2}
 \left[\log2+3\log(36\kappa_\star)\right].
\end{align*}
This is the budget of a phase of the existing controller, not a
parameter supplied to it. For every $K\ge2(T_{\mathrm{adapt}}-1)$,
\begin{equation}\label{eq:controlled-finite-tail}
 f(x^K)-f_\star\le \varepsilon_{\mathrm{loc}}
 \exp\left[-\frac{\log2}{232\sqrt{\kappa_\star}}
                    (K-4T_{\mathrm{adapt}})\right].
\end{equation}
Consequently, for every $0<\varepsilon<\varepsilon_{\mathrm{loc}}$, objective
accuracy $f(x^K)-f_\star\le\varepsilon$ is guaranteed once
\begin{equation}\label{eq:controlled-finite-complexity}
 K\ge\left\lceil4T_{\mathrm{adapt}}
       +\frac{232\sqrt{\kappa_\star}}{\log2}
                     \log\frac{\varepsilon_{\mathrm{loc}}}{\varepsilon}\right\rceil.
\end{equation}
In particular, a sufficient number of accepted steps is
\begin{equation}\label{eq:controlled-separated-costs}
\begin{aligned}
 O\!\Biggl(&1+D_0\sqrt{
 \frac{\tfrac32(L_0+\sqrt{4HL_0D_0})
                         +\tfrac{2048}{3}HD_0}
      {\varepsilon_{\mathrm{loc}}}}\\
 &+\sqrt{\kappa_\star}\left[
       \log(2+\kappa_\star)+\log\frac{\varepsilon_{\mathrm{loc}}}{\varepsilon}
                       \right]\Biggr),
\end{aligned}
\end{equation}
with a universal implicit constant. None of these analysis
parameters changes the oracle counts of
Theorem~\ref{thm:automatic-acceleration}.

\label{thm:global-bt}
Under Assumptions~\ref{ass:convex}--\ref{ass:hessian}, take
$0<H_{\mathrm{init}}\le2H$. The adaptive rule is well defined for
any search spaces containing the current gradient.
Every trial loop is finite, all accepted iterates belong to
$\mathcal C_0$, and
\begin{equation}\label{eq:global-Mbound}
 0<H_k\le H_{\max}:=2H.
\end{equation}
